-- GENERATED by gen_mxh3_vault.py -- models are generated, never hand-edited.
--   SAT_CLAIM_PROVIDER_BILLING
--   anchor      : HUB_CLAIM
--   grain       : Multi-Active SCD2 (data_7.js sats[].hist)
--   child key   : Bill Number
--   feeders     : 2 -- one per (view, DECLARED ANCHOR EXPRESSION)
--   payload     : 4 attribute(s), NULL-PADDED TO THE SATELLITE
--
--   The child key is the MODEL'S declared key, read from data_7.js
--   sats[].childkey keyed by sats[].code. target.key_name is the HUB key
--   name and is null on all 1,888 satellite rows, so it is never read here.
--
--   The hashdiff is GUARDED against an all-null input: without the guard
--   every all-null row hashes to ONE value and the population collapses.

with feeders as (select * from (
    select
        md5(upper(HUB_CLAIM_BK__K0)) as HUB_CLAIM_HK,
        coalesce(nullif(trim(BILL_NUMBER),''),'') as BILL_NUMBER,
        TOTAL_BILLED_AMOUNT as BILLED_AMOUNT,
        null::varchar as DISALLOWED_AMOUNT,
        null::varchar as DISALLOWANCE_REASON,
        'MAXI_HLTH_CLM_VW_DATA_CLAIM_DETAIL_CLAIMDETAIL_ATTRIBUTE_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_clm_cd_clmdetail_apv') }}
    where HUB_CLAIM_K0__EMIT
    union all
    select
        md5(upper(HUB_CLAIM_BK__K0)) as HUB_CLAIM_HK,
        coalesce(nullif(trim(BILL_NUMBER),''),'') || '#' || coalesce(nullif(trim(SERVICE_CODE),''),'') as BILL_NUMBER,
        BILLED_AMOUNT as BILLED_AMOUNT,
        REJECTED_AMOUNT as DISALLOWED_AMOUNT,
        REJECTION_REASON as DISALLOWANCE_REASON,
        'MAXI_HLTH_CLM_VW_DATA_CLAIM_DETAIL_LIST_OF_COVERS_ENTITY_HEADS_ENTITY_GRID_ROWS_ROW_ATTRIBUTES_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_clm_cd_loc_eh_egr_rattr_pv') }}
    where HUB_CLAIM_K0__EMIT
)), hashed as (select *,
        case when BILLED_AMOUNT is not null or DISALLOWED_AMOUNT is not null or DISALLOWANCE_REASON is not null
             then md5(upper(coalesce(BILLED_AMOUNT::varchar,'') || '||' || coalesce(DISALLOWED_AMOUNT::varchar,'') || '||' || coalesce(DISALLOWANCE_REASON::varchar,'')))
        end as SAT_CLAIM_PROVIDER_BILLING_HASHDIFF
    from feeders)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_PROVIDER_BILLING_HASHDIFF is not null
  and BILL_NUMBER is not null
